var datum, txt;

// Beschreibe diese Funktion …
async function Logfile(datum, txt) {
    if (getState('0_userdata.0.go-e.DebugAktiv').val) {
      require('fs').appendFileSync('/opt/iobroker/log/' + datum + ' - Cupra.log', formatDate(new Date(), "hh:mm:ss") + " \t" + txt + "\n");}
}


// ------->>>> Logfile

// ------->>>> LIMITS
// minAmpere
setState('go-e.0.ampere' /* Ampere for PWM (amp) */, parseFloat(getState('0_userdata.0.go-e.minA').val), true);
on({ id: [].concat(['go-e.0.ampere']), change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if (getState('go-e.0.ampere').val < getState('0_userdata.0.go-e.minA').val) {
    setState('go-e.0.ampere' /* Ampere for PWM (amp) */, parseFloat(getState('0_userdata.0.go-e.minA').val), true);
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '# go-E / Limits/ minAmpere');
  } else if (getState('go-e.0.ampere').val > getState('go-e.0.max_ampere').val) {
    setState('go-e.0.ampere' /* Ampere for PWM (amp) */, parseFloat(getState('go-e.0.max_ampere').val), true);
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '# go-E / Limits/ PWM Ampere');
  }
});
// maxAmpere
on({ id: [].concat(['0_userdata.0.go-e.minA']).concat(['0_userdata.0.go-e.maxA']), change: 'ne' }, async (obj) => {
  if (getState('0_userdata.0.go-e.minA').val > getState('0_userdata.0.go-e.maxA').val) {
    setState('0_userdata.0.go-e.maxA' /* maxAmpere */, getState('0_userdata.0.go-e.minA').val);
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '# go-E / Limits/ maxAmpere');
  }
});


